INSERT INTO item VALUES (1598,'Phasing','Armor','Psionic','Yes','Strong psychoportation',NULL,'+65,520 gp','13','Craft Psionic Arms and Armor, psionic phase door',NULL,NULL,'\n      <div topic=\"Phasing\" level=\"8\"><p><b>Phasing:</b> The wearer of this kind of armor can move through wooden, plaster, or stone walls, but not other materials. The wearer can call on this special ability as a standard action. When the phasing ability is active, the wearer can pass through a wall or some other kind of appropriate object for a total distance of 60 feet per day (see below), breaking this distance up into several smaller passages or one long one, as desired. A wearer who exceeds this daily distance limit while inside solid material is ejected from the material at the point of entry, ending up prone in front of the now impassable barrier.</p><p>Phasing through a wall that separates two adjacent squares on the grid counts as 5 feet of distance. Phasing through a wall or barrier of any greater thickness counts as a distance equal to the barrier\'s thickness plus 5 feet.</p><p>feet of distance.</p><p>Strong psychoportation; ML 13th; Craft Psionic Arms and Armor, <i>psionic phase door</i>; Price +65,520 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1599,'Power Resistance (13)','Armor, Shield','Psionic','Yes','Moderate clairsentience',NULL,'+2 bonus','9','Craft Psionic Arms and Armor, power resistance',NULL,NULL,'\n      <div topic=\"Power Resistance\" level=\"8\"><p><b>Power Resistance:</b> This kind of armor or shield grants the wearer power resistance while it is worn. The power resistance can be 13, 15, 17, or 19, depending on the amount that was built into the armor or shield.</p><p>Moderate clairsentience; ML 9th; Craft Psionic Arms and Armor, <i>power resistance</i>; Price +2 bonus (PR 13), +3 bonus (PR 15), +4 bonus (PR 17), or +5 bonus (PR 19).</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1600,'Power Resistance (15)','Armor, Shield','Psionic','Yes','Moderate clairsentience',NULL,'+3 bonus','9','Craft Psionic Arms and Armor, power resistance',NULL,NULL,'\n      <div topic=\"Power Resistance\" level=\"8\"><p><b>Power Resistance:</b> This kind of armor or shield grants the wearer power resistance while it is worn. The power resistance can be 13, 15, 17, or 19, depending on the amount that was built into the armor or shield.</p><p>Moderate clairsentience; ML 9th; Craft Psionic Arms and Armor, <i>power resistance</i>; Price +2 bonus (PR 13), +3 bonus (PR 15), +4 bonus (PR 17), or +5 bonus (PR 19).</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1601,'Power Resistance (17)','Armor, Shield','Psionic','Yes','Moderate clairsentience',NULL,'+4 bonus','9','Craft Psionic Arms and Armor, power resistance',NULL,NULL,'\n      <div topic=\"Power Resistance\" level=\"8\"><p><b>Power Resistance:</b> This kind of armor or shield grants the wearer power resistance while it is worn. The power resistance can be 13, 15, 17, or 19, depending on the amount that was built into the armor or shield.</p><p>Moderate clairsentience; ML 9th; Craft Psionic Arms and Armor, <i>power resistance</i>; Price +2 bonus (PR 13), +3 bonus (PR 15), +4 bonus (PR 17), or +5 bonus (PR 19).</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1602,'Power Resistance (19)','Armor, Shield','Psionic','Yes','Moderate clairsentience',NULL,'or +5 bonus','9','Craft Psionic Arms and Armor, power resistance',NULL,NULL,'\n      <div topic=\"Power Resistance\" level=\"8\"><p><b>Power Resistance:</b> This kind of armor or shield grants the wearer power resistance while it is worn. The power resistance can be 13, 15, 17, or 19, depending on the amount that was built into the armor or shield.</p><p>Moderate clairsentience; ML 9th; Craft Psionic Arms and Armor, <i>power resistance</i>; Price +2 bonus (PR 13), +3 bonus (PR 15), +4 bonus (PR 17), or +5 bonus (PR 19).</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1603,'Quickness','Armor','Psionic','Yes','Faint psychoportation',NULL,'+1 bonus','4','Craft Psionic Arms and Armor, burst',NULL,NULL,'\n      <div topic=\"Quickness\" level=\"8\"><p><b>Quickness:</b> This kind of armor increases the wearer\'s speed by 5 feet. Thus, a character whose normal speed in armor is 20 feet moves 25 feet in <i>armor of quickness</i>. </p><p>Faint psychoportation; ML 4th; Craft Psionic Arms and Armor, <i>burst</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1604,'Radiant','Armor','Psionic','Yes','Moderate psychokinesis',NULL,'+4 bonus','9','Craft Psionic Arms and Armor, energy adaptation',NULL,NULL,'\n      <div topic=\"Radiant\" level=\"8\"><p><b>Radiant:</b> The wearer of this kind of armor gains resistance 10 against energy attacks (acid, cold, electricity, fire, or sonic). The armor absorbs the first 10 points of damage dealt by any such attack, and this absorption causes it to radiate light for a number of rounds equal to the points of damage absorbed. This light is sufficient to illuminate a 60-foot-radius area.</p><p>If the armor absorbs more damage while it is radiating light, the newer radiant effect overlaps (does not stack with) the effect that was already in place.</p><p>Moderate psychokinesis; ML 9th; Craft Psionic Arms and Armor, <i>energy adaptation</i>; Price +4 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1605,'Ranged','Shield','Psionic','Yes','Faint psychokinesis',NULL,'+1 bonus','5','Craft Psionic Arms and Armor, far hand',NULL,NULL,'\n      <div topic=\"Ranged\" level=\"8\"><p><b>Ranged:</b> The wielder of a ranged shield can throw it in combat, with a range increment of 30 feet. While in the air, the shield is treated in all ways as a ranged weapon and cannot be blocked or grabbed except by those with appropriate feats. No matter the size of the wielder, a buckler or light shield deals 1d6 points of damage and a heavy one 1d8 points. (A tower shield cannot be created with this special ability.) The wielder\'s Strength modifier and the shield\'s enhancement bonus add to the base damage.</p><p>A ranged shield flies through the air back to the creature that threw it. It returns to the wielder just before the creature\'s next turn (and is therefore ready to use again in that turn).</p><p>Catching a ranged shield when it comes back is a free action. If the wielder can\'t catch it, or if the wielder has moved since throwing it, the shield drops to the ground in the square from which it was thrown.</p><p>Faint psychokinesis; ML 5th; Craft Psionic Arms and Armor,  <i>far hand</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1606,'Seeing','Armor','Psionic','Yes','Faint clairsentience',NULL,'+6,000 gp','5','Craft Psionic Arms and Armor, ubiquitous vision',NULL,NULL,'\n      <div topic=\"Seeing\" level=\"8\"><p><b>Seeing:</b> This kind of armor grants a wider than normal field of vision, so that opponents flanking the wearer gain only a +1 bonus on their attack rolls instead of +2 (rogues still get their full sneak attack damage because the wearer is still flanked). The wearer gains a +1 enhancement bonus on Spot checks but takes a -2 penalty on saves against gaze attacks.</p><p>Faint clairsentience; ML 5th; Craft Psionic Arms and Armor, <i>ubiquitous vision</i>; Price +6,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1607,'Time Buttress','Shield','Psionic','Yes','Strong psychoportation',NULL,'+5 bonus','17','Craft Psionic Arms and Armor, timeless body',NULL,NULL,'\n      <div topic=\"Time Buttress\" level=\"8\"><p><b>Time Buttress:</b> This kind of shield gives the wielder a chance to avoid telling blows by using time itself as a shield. Once per day, the wielder can use <i>timeless body</i> as though manifesting the power.</p><p>Strong psychoportation; ML 17th; Craft Psionic Arms and Armor, <i>timeless body</i>; Price +5 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1608,'Vanishing','Armor, Shield','Psionic','Yes','Faint psychokinesis',NULL,'+3 bonus','5','Craft Psionic Arms and Armor, cloud mind',NULL,NULL,'\n      <div topic=\"Vanishing\" level=\"8\"><p><b>Vanishing:</b> On command, this suit of armor or shield renders its wearer and all the wearer\'s equipment invisible to the minds of others, as if he had manifested the power <i>cloud mind</i>. The wearer can use this ability twice per day.</p><p>Faint psychokinesis; ML 5th; Craft Psionic Arms and Armor, <i>cloud mind</i>; Price +3 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1609,'Wall','Shield','Psionic','Yes','Strong metacreativity',NULL,'+20,160 gp','12','Craft Psionic Arms and Armor, wall of ectoplasm',NULL,NULL,'\n      <div topic=\"Wall\" level=\"8\"><p><b>Wall:</b> As a standard action once per day, the wielder can drop this kind of shield at his feet and command a <i>wall of ectoplasm</i> (as the power) to come into being, with the shield as the point of origin for the effect. This effect forms a wall whose area is up to twelve 10-foot squares or a sphere or hemisphere with a radius of up to 12 feet. The wall dissipates after 7 minutes, or sooner if the wielder of the shield reclaims it (thus dismissing the effect).</p><p>Strong metacreativity; ML 12th; Craft Psionic Arms and Armor, <i>wall of ectoplasm</i>; Price +20,160 gp.</p><p/>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1610,'Bodyfeeder','Weapon','Psionic','Yes','Strong psychometabolism',NULL,'+3 bonus','12','Craft Psionic Arms and Armor, claws of the vampire',NULL,NULL,'\n      <div topic=\"Bodyfeeder\" level=\"8\"><p><b>Bodyfeeder:</b> All feeder weapons have a special ability that functions only upon scoring a successful critical hit. A bodyfeeder weapon grants its wielder temporary hit points equal to the total damage dealt by a successful critical hit. These temporary hit points last for 10 minutes. Thus, if the wielder of a bodyfeeder weapon successfully scores a critical hit while the wielder still enjoys temporary hit points from a previous critical hit, the wielder gains only the better of the two values: either his current number of temporary hit points, or the new influx of temporary hit points, whichever is higher.</p><p>Strong psychometabolism; ML 12th; Craft Psionic Arms and Armor, <i>claws of the vampire</i>; Price +3 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1611,'Collision','Weapon','Psionic','Yes','Moderate metacreativity',NULL,'+2 bonus','10','Craft Psionic Arms and Armor, matter manipulation',NULL,NULL,'\n      <div topic=\"Collision\" level=\"8\"><p><b>Collision:</b> Collision weapons psionically increase their own mass at the end point of each swing or shot. Such weapons deal an extra 5 points of damage on each successful strike, in addition to the weapon\'s enhancement bonus. Bows, crossbows, and slings bestow the extra damage upon their ammunition.</p><p>Moderate metacreativity; ML 10th; Craft Psionic Arms and Armor, <i>matter manipulation</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1612,'Coup De Grace','Weapon','Psionic','Yes','Strong telepathy',NULL,'+5 bonus','19','Craft Psionic Arms and Armor, psionic dominate',NULL,NULL,'\n      <div topic=\"Coup De Grace\" level=\"8\"><p><b>Coup de Grace:</b> Coup de grace weapons are exceptionally dangerous. On a successful critical hit, the foe must succeed on a DC 27 Will save or be paralyzed for 1 round. While this ability does work on creatures that are immune to extra damage from critical hits, it does not work on creatures without an Intelligence score. Bows, crossbows, and slings bestow this ability on their ammunition.</p><p>Strong telepathy; ML 19th; Craft Psionic Arms and Armor, <i>psionic dominate</i>; Price +5 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1613,'Dislocator','Weapon','Psionic','Yes','Strong psychoportation',NULL,'+3 bonus','12','Craft Psionic Arms and Armor, psionic teleport',NULL,NULL,'\n      <div topic=\"Dislocator\" level=\"8\"><p><b>Dislocator:</b> The wielder of this kind of weapon can attempt to dislocate a designated foe up to three times per day. On a successful hit, the foe must succeed on a DC 17 Will save or be teleported 1-100 miles in a random direction. If the weapon misses, the use is wasted. Bows, crossbows, and slings bestow this ability on their ammunition.</p><p>Strong psychoportation; ML 12th; Craft Psionic Arms and Armor, <i>psionic teleport</i>; Price +3 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1614,'Dissipater','Weapon','Psionic','Yes','Strong metacreativity',NULL,'+1 bonus','12','Craft Psionic Arms and Armor, dismiss ectoplasm',NULL,NULL,'\n      <div topic=\"Dissipater\" level=\"8\"><p><b>Dissipater:</b> This kind of weapon is devastating to creatures and objects composed of or originally formed from ectoplasm (such as astral constructs, walls of ectoplasm, creatures in ectoplasmic form, and items created using the metacreativity discipline). Against qualifying targets, a dissipater weapon ignores damage reduction and hardness, and treats all successful hits as critical hits.</p><p>Strong metacreativity; ML 12th; Craft Psionic Arms and Armor, <i>dismiss ectoplasm</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1615,'Great Dislocator','Weapon','Psionic','Yes','Strong psychoportation',NULL,'+4 bonus','12','Craft Psionic Arms and Armor, psionic plane shift',NULL,NULL,'\n      <div topic=\"Great Dislocator\" level=\"8\"><p><b>Great Dislocator:</b> The wielder of this kind of weapon can attempt to greatly dislocate a designated foe up to three times per day. On a successful hit, the foe must succeed on a DC 20 Will save or be cast into a random alternate plane of existence. If the weapon misses, the use is wasted. Bows, crossbows, and slings bestow this ability upon their ammunition.</p><p>Strong psychoportation; ML 12th; Craft Psionic Arms and Armor, <i>psionic plane shift</i>; Price +4 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1616,'Lucky','Weapon','Psionic','Yes','Moderate clairsentience',NULL,'+1 bonus','8','Craft Psionic Arms and Armor, fate of one',NULL,NULL,'\n      <div topic=\"Lucky\" level=\"8\"><p><b>Lucky:</b> A lucky weapon offers a second chance at success. Once per day, the wielder can reroll a failed attack roll (whether a single attack or one in a series of multiple attacks) as a free action. The rerolled attack uses the same bonuses or penalties as the missed roll.</p><p>Moderate clairsentience; ML 8th; Craft Psionic Arms and Armor,  <i>fate of one</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1617,'Manifester','Weapon','Psionic','Yes','Moderate clairsentience',NULL,'+16,000 gp','8','Craft Psionic Arms and Armor, knowledge of any 3rd-level power',NULL,NULL,'\n      <div topic=\"Manifester\" level=\"8\"><p><b>Manifester:</b> This kind of weapon generates 5 power points once per day that the wearer can use when manifesting a power he knows. These power points must all be used on the same power. As usual, a psionic character cannot pay a power\'s cost with power points from more than one source, so the power points in the shield must be used for discrete manifestations.</p><p>Moderate clairsentience; ML 8th; Craft Psionic Arms and Armor, knowledge of any 3rd-level power; Price +16,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1618,'Mindcrusher','Weapon','Psionic','Yes','Strong psychometabolism',NULL,'+2 bonus','12','Craft Psionic Arms and Armor, psychic vampire',NULL,NULL,'\n      <div topic=\"Mindcrusher\" level=\"8\"><p><b>Mindcrusher:</b> Any psionic creature struck in combat by a mindcrusher weapon loses a number of power points equal to half the amount of hit point damage the weapon deals (only the base damage of the weapon contributes to the power point loss; additional damage from high Strength or other sources does not cause additional power point loss). A psionic creature that is out of power points (or has none) must succeed on a DC 17 Will save or take 1d2 points of Wisdom damage.</p><p>Strong psychometabolism; ML 12th; Craft Psionic Arms and Armor, <i>psychic vampire</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1619,'Mindfeeder','Weapon','Psionic','Yes','Strong psychometabolism',NULL,'+3 bonus','15','Craft Psionic Arms and Armor, psychic vampire',NULL,NULL,'\n      <div topic=\"Mindfeeder\" level=\"8\"><p><b>Mindfeeder:</b> All feeder weapons have a special ability that functions only upon scoring a successful critical hit. Once per day, a mindfeeder weapon grants its wielder temporary power points equal to the total lethal damage dealt by a successful critical hit. The wielder must decide to use the mindfeeder ability after successfully confirming a critical hit, but prior to rolling critical hit damage. These temporary power points last for 10 minutes. The wielder may not exceed his natural maximum power points per day using the mindfeeder ability. The wielder gains power points even if the target has none (effectively, its hit point damage is converted to power points). Constructs and undead are not subject to mindfeeder weapons. As with temporary hit points, temporary power points do not stack with each other; they overlap. Thus, if a mindfeeder weapon successfully scores a critical hit while the wielder still enjoys temporary power points from a previous critical hit, the wielder gains only the better of the two values: either her current number of temporary power points, or the new influx of temporary power points, whichever is higher.</p><p>Strong psychometabolism; ML 15th; Craft Psionic Arms and Armor, <i>psychic vampire</i>; Price +3 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1620,'Parrying','Weapon','Psionic','Yes','Faint clairsentience',NULL,'+8,000 gp','5','Craft Psionic Arms and Armor, defensive precognition',NULL,NULL,'\n      <div topic=\"Parrying\" level=\"8\"><p><b>Parrying:</b> A parrying weapon perceives an instant into the future, and of its own accord resists melee and ranged attacks aimed at the wielder, granting a +1 insight bonus to the wielder\'s Armor Class. The weapon is so adept at parrying that it even affects incoming powers, granting the wielder a +1 insight bonus on saving throws. The bonuses are granted whenever the wielder holds the weapon, even if flat-footed.</p><p>Faint clairsentience; ML 5th; Craft Psionic Arms and Armor, <i>defensive precognition</i>; Price +8,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1621,'Power Storing','Weapon','Psionic','Yes','Strong psychokinesis',NULL,'+1 bonus','12','Craft Psionic Arms and Armor, creator must be a manifester of at least 12th level',NULL,NULL,'\n      <div topic=\"Power Storing\" level=\"8\"><p><b>Power Storing:</b> A power storing weapon allows a manifester to store a single targeted power of up to 5 power points in the weapon. (The power must have a manifesting time of 1 standard action.) Any time the weapon strikes a creature and the creature takes damage from it, the weapon can immediately manifest the power on that creature as a swift action if the wielder desires. (This ability is an exception to the rule that manifesting a power from an item takes at least as long as manifesting that power normally.) Once the power is manifested, the weapon is empty, and a manifester can imbed any other targeted power of up to 5 power points into it. The weapon telepathically whispers to the wearer the name of the power currently stored within it. A randomly generated power storing weapon has a 50% chance to have a power stored in it already.</p><p>Strong psychokinesis; ML 12th; Craft Psionic Arms and Armor, creator must be a manifester of at least 12th level; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1622,'Psibane','Weapon','Psionic','Yes','Strong clairsentience',NULL,'+2 bonus','15','Craft Psionic Arms and Armor, bend reality',NULL,NULL,'\n      <div topic=\"Psibane\" level=\"8\"><p><b>Psibane:</b> A psibane weapon is crafted to oppose psionic beings. When used against such creatures, its effective enhancement bonus is 2 higher than its actual enhancement bonus. It deals an extra 2d6 points of damage against psionic opponents. It bestows one negative level on any psionic creature attempting to wield it. This negative level remains as long as the weapon is in hand and disappears when the weapon is no longer wielded. This negative level never results in actual level loss, but it cannot be overcome in any way while the weapon is wielded. Psibane bows, crossbows, and slings bestow this ability upon their ammunition.</p><p>Strong clairsentience; ML 15th; Craft Psionic Arms and Armor, <i>bend reality</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1623,'Psychic','Weapon','Psionic','Yes','Strong clairsentience',NULL,'+35,000','17','Craft Psionic Arms and Armor, reality revision',NULL,NULL,'\n      <div topic=\"Psychic\" level=\"8\"><p><b>Psychic:</b> A psychic weapon\'s power depends on its wielder. In the hands of a nonpsionic creature, the weapon possesses the qualities of a nonmagical, nonpsionic masterwork weapon. When wielded by a psionic creature, this weapon has an enhancement bonus based on the wielder\'s current power point reserve, as shown on the following table. The weapon\'s enhancement bonus decreases as the wielder spends power points, and it increases whenever the wielder gains enough power points (by any means) to put his power point reserve into the next higher category.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Power Point Reserve</b><br/></td> <td><b>Enhancement Bonus</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1-4<br/></td>\n<td>+1<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5-29<br/></td>\n<td>+2<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>30-79<br/></td>\n<td>+3<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>80-129<br/></td>\n<td>+4<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>130 or higher<br/></td>\n<td>+5<br/></td>\n\n</tr>\n</table><p>Strong clairsentience; ML 17th; Craft Psionic Arms and Armor, <i>reality revision</i>; Price +35,000.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1624,'Psychokinetic','Weapon','Psionic','Yes','Moderate psychokinesis',NULL,'+1 bonus','10','Craft Psionic Arms and Armor, concussion blast',NULL,NULL,'\n      <div topic=\"Psychokinetic\" level=\"8\"><p><b>Psychokinetic:</b> Upon command, a psychokinetic weapon glows from the inside with lethal psionic energy. The energy does not harm the hands that hold the weapon. Such a weapon deals an extra 1d4 points of damage on a successful hit. This extra damage is ectoplasmic in nature and is not affected by damage reduction. Bows, crossbows, and slings bestow this ability upon their ammunition.</p><p>Moderate psychokinesis; ML 10th; Craft Psionic Arms and Armor, <i>concussion blast</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1625,'Psychokinetic Burst','Weapon','Psionic','Yes','Strong psychokinesis',NULL,'+2 bonus','12','Craft Psionic Arms and Armor, concussion blast',NULL,NULL,'\n      <div topic=\"Psychokinetic Burst\" level=\"8\"><p><b>Psychokinetic Burst:</b> This weapon functions as a psychokinetic weapon that also releases a blast of destructive psionic energy upon scoring a successful critical hit. In addition to the extra damage of the psychokinetic ability (see above), a psychokinetic burst weapon deals an extra 1d6 points of damage on a successful critical hit. If the weapon\'s critical multiplier is x3, add 2d6 points of extra damage instead, and if the multiplier is x4, add 3d6 points of extra damage. This extra damage is ectoplasmic in nature and is not affected by damage reduction. Bows, crossbows, and slings bestow this ability upon their ammunition.</p><p>Strong psychokinesis; ML 12th; Craft Psionic Arms and Armor, <i>concussion blast</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1626,'Soulbreaker','Weapon','Psionic','Yes','Strong telepathy',NULL,'+3 bonus','12','Craft Psionic Arms and Armor, mindwipe',NULL,NULL,'\n      <div topic=\"Soulbreaker\" level=\"8\"><p><b>Soulbreaker:</b> This weapon has a special ability that functions only upon scoring a successful critical hit. On a successful critical hit, a soulbreaker weapon bestows one negative level on the foe. One day after being struck, if the negative levels have not been purged, the subject must succeed on a DC 18 Fortitude save for each negative level or lose a character level.</p><p>Strong telepathy; ML 12th; Craft Psionic Arms and Armor, <i>mindwipe</i>; Price +3 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1627,'Sundering','Weapon','Psionic','Yes','Faint metacreativity',NULL,'+1 bonus','5','Craft Psionic Arms and Armor, Great Sunder, metaphysical weapon',NULL,NULL,'\n      <div topic=\"Sundering\" level=\"8\"><p><b>Sundering:</b> This kind of weapon allows a wielder to attack opponents\' weapons as if he had the Improved Sunder feat.</p><p>Faint metacreativity; ML 5th; Craft Psionic Arms and Armor, Great Sunder, <i>metaphysical weapon</i>; Price +1 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1628,'Suppression','Weapon','Psionic','Yes','Moderate psychokinesis',NULL,'+2 bonus','10','Craft Psionic Arms and Armor, dispel psionics',NULL,NULL,'\n      <div topic=\"Suppression\" level=\"8\"><p><b>Suppression:</b> An opponent or object struck by this kind of weapon is subject to a targeted <i>dispel psionics</i> power. The wielder makes a dispel check (1d20 + 5 + manifester level, maximum +15) against a DC of 11 + the manifester level of the power to be dispelled. Bows, crossbows, and slings bestow this ability upon their ammunition, but can do so only three times per day.</p><p>Moderate psychokinesis; ML 10th; Craft Psionic Arms and Armor, <i>dispel psionics</i>; Price +2 bonus.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1629,'Teleporting','Weapon','Psionic','Yes','Faint psychoportation',NULL,'+1 bonus','5','Craft Psionic Arms and Armor, psionic dimension door',NULL,NULL,'\n      <div topic=\"Teleporting\" level=\"8\"><p><b>Teleporting:</b> This ability can be imbedded only in weapons that can be thrown. A teleporting weapon returns through the Astral Plane to the creature that threw it. It teleports into the throwing creature\'s empty hand in the round following the round when it was thrown, just before that creature\'s turn. It is therefore ready to use again on that turn.</p><p>Faint psychoportation; ML 5th; Craft Psionic Arms and Armor,  <i>psionic dimension door</i>; Price +1 bonus.</p><p/>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1630,'Astral Legion','Psicrown','Psionic','No','Strong metacreativity',NULL,'47,250 gp','18','Craft Psicrown, astral construct',NULL,NULL,'\n      <div topic=\"Astral Legion\" level=\"8\"><p><b>Astral Legion:</b> This psicrown has 900 power points. It is made from white silk interwoven with crystalline strands of thread. It allows use of the following power.</p><ul>\n <li> <i>Astral construct</i> </li>\n</ul><p>Strong metacreativity; ML 18th; Craft Psicrown, <i>astral construct</i>; Price 47,250 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1631,'Beast','Psicrown','Psionic','No','Moderate psychometabolism',NULL,'33,750 gp','9','Craft Psicrown, Claw of energy, duodimensional claw, prevenom, psionic lion\'s charge, truevenom',NULL,NULL,'\n      <div topic=\"Beast\" level=\"8\"><p><b>Beast:</b> This psicrown has 450 power points. It is made from a prickly collection of bear claws and snake fangs. It allows use of the following powers.</p><ul>\n <li> <i>Claw of energy</i></li>\n <li> <i>Duodimensional claw</i></li>\n <li> <i>Prevenom</i></li>\n <li> <i>Psionic lion\'s charge</i></li>\n <li> <i>Truevenom</i></li>\n</ul><p>Moderate psychometabolism; ML 9th; Craft Psicrown, <i>Claw of energy</i>,  <i>duodimensional claw</i>,  <i>prevenom</i>,  <i>psionic lion\'s charge</i>,  <i>truevenom</i>; Price 33,750 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1632,'Cautious Warrior','Psicrown','Psionic','No','Moderate psychometabolism',NULL,'32,063 gp','9','Craft Psicrown, adapt body, body adjustment, defensive precognition, inertial barrier',NULL,NULL,'\n      <div topic=\"Cautious Warrior\" level=\"8\"><p><b>Cautious Warrior:</b> This psicrown has 450 power points. It is made from a shining iron alloy, similar to the material of a metallic shield. It allows use of the following powers.</p><ul>\n <li> <i>Adapt body</i></li>\n <li> <i>Body adjustment</i></li>\n <li> <i>Precognition</i>,  <i>defensive</i></li>\n <li> <i>Inertial barrier</i></li>\n</ul><p>Moderate psychometabolism; ML 9th; Craft Psicrown, <i>adapt body</i>,  <i>body adjustment</i>,  <i>defensive precognition</i>,  <i>inertial barrier</i>; Price 32,063 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1633,'Discerning Watcher','Psicrown','Psionic','No','Moderate clairsentience',NULL,'51,469 gp','9','Craft Psicrown, aura sight, clairtangent hand, clairvoyant sense, psionic darkvision, psionic true seeing, remote viewing',NULL,NULL,'\n      <div topic=\"Discerning Watcher\" level=\"8\"><p><b>Discerning Watcher:</b> This psicrown has 450 power points. It is made from pure transparent crystal. It allows use of the following powers.</p><ul>\n <li> <i>Aura sight</i></li>\n <li> C<i>lairtangent hand</i></li>\n <li> <i>Clairvoyant sense</i></li>\n <li> <i>Darkvision</i>,  <i>psionic</i></li>\n <li> <i>Remote viewing</i></li>\n <li> <i>True seeing</i>,  <i>psionic</i></li>\n</ul><p>Moderate clairsentience; ML 9th; Craft Psicrown, <i>aura sight</i>,  <i>clairtangent hand</i>,  <i>clairvoyant sense</i>,  <i>psionic darkvision</i>,  <i>psionic true seeing</i>,  <i>remote viewing</i>; Price 51,469 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1634,'Dominator','Psicrown','Psionic','No','Moderate telepathy',NULL,'20,250 gp','9','Craft Psicrown, psionic charm, psionic dominate, psionic suggestion',NULL,NULL,'\n      <div topic=\"Dominator\" level=\"8\"><p><b>Dominator:</b> This psicrown has 450 power points. It is made from gray iron and is shaped into an intricately fluted crown. It allows use of the following powers.</p><ul>\n <li> <i>Charm</i>,  <i>psionic</i></li>\n <li> <i>Dominate</i>,  <i>psionic</i></li>\n <li> <i>Suggestion</i>,  <i>psionic</i></li>\n</ul><p>Moderate telepathy; ML 9th; Craft Psicrown, <i>psionic charm</i>,  <i>psionic dominate</i>,  <i>psionic suggestion</i>; Price 20,250 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1635,'Evader','Psicrown','Psionic','No','Moderate psychoportation',NULL,'28,500 gp','8','Craft Psicrown, catfall, hustle, psionic fly, psionic freedom of movement, wall walker',NULL,NULL,'\n      <div topic=\"Evader\" level=\"8\"><p><b>Evader:</b> This psicrown has 400 power points. It is made from silk, usually dyed emerald green, with an emerald crystal affixed to the material. It allows use of the following powers.</p><ul>\n <li> <i>Catfall</i></li>\n <li> <i>Hustle</i></li>\n <li> <i>Fly</i>,  <i>psionic</i></li>\n <li> <i>Freedom of movement</i>,  <i>psionic</i></li>\n <li> <i>Wall walker</i></li>\n</ul><p>Moderate psychoportation; ML 8th; Craft Psicrown, <i>catfall</i>,  <i>hustle</i>,  <i>psionic fly</i>,  <i>psionic freedom of movement</i>,  <i>wall walker</i>; Price 28,500 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1636,'Fiery Ruin','Psicrown','Psionic','No','Strong psychokinesis',NULL,'67,500 gp','15','Craft Psicrown, energy ball, energy cone, energy missile, energy stun, fiery discorporation',NULL,NULL,'\n      <div topic=\"Fiery Ruin\" level=\"8\"><p><b>Fiery Ruin:</b> This psicrown has 750 power points. It is made from reddish iron and is shaped into a twisted circlet studded with reddish crystals. It allows use of the following powers.</p><ul>\n <li> <i>Energy ball</i></li>\n <li> <i>Energy cone</i></li>\n <li> <i>Energy missile</i></li>\n <li> <i>Energy stun</i></li>\n <li> <i>Fiery discorporation</i></li>\n</ul><p>Strong psychokinesis; ML 15th; Craft Psicrown, <i>energy ball</i>,  <i>energy cone</i>,  <i>energy missile</i>,  <i>energy stun</i>,  <i>fiery discorporation</i>;  Price 67,500 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1637,'Great Dominator','Psicrown','Psionic','No','Strong telepathy',NULL,'45,000 gp','15','Craft Psicrown, psionic charm, psionic dominate, psionic suggestion',NULL,NULL,'\n      <div topic=\"Great Dominator\" level=\"8\"><p><b>Great Dominator:</b> This psicrown has 750 power points. It is made from black iron without further ornamentation. It allows use of the following powers.</p><ul>\n <li> <i>Charm</i>,  <i>psionic</i></li>\n <li> <i>Suggestion</i>,  <i>psionic</i></li>\n <li> <i>Dominate</i>,  <i>psionic</i></li>\n</ul><p>Strong telepathy; ML 15th; Craft Psicrown, <i>psionic charm</i>,  <i>psionic dominate</i>,  <i>psionic suggestion</i>; Price 45,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1638,'Temporal Juggler','Psicrown','Psionic','No','Strong psychoportation',NULL,'95,625 gp','17','Craft Psicrown, temporal acceleration, time hop, timeless body',NULL,NULL,'\n      <div topic=\"Temporal Juggler\" level=\"8\"><p><b>Temporal Juggler:</b> This psicrown has 850 power points. It is made from silk, usually dyed in several colors, with a clear crystal affixed to the material. It allows use of the following powers.</p><ul>\n <li> <i>temporal acceleration</i></li>\n <li> <i>Time hop</i></li>\n <li> <i>Timeless body</i></li>\n</ul><p>Strong psychoportation; ML 17th; Craft Psicrown, <i>temporal acceleration</i>,  <i>time hop</i>,  <i>timeless body</i>; Price 95,625 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1639,'Traveler','Psicrown','Psionic','No','Strong psychoportation',NULL,'80,156 gp','15','Craft Psicrown, astral traveler, psionic dimension door, psionic greater teleport, psionic teleport',NULL,NULL,'\n      <div topic=\"Traveler\" level=\"8\"><p><b>Traveler:</b> This psicrown has 750 power points. It is made from silk, usually dyed emerald green, with an emerald crystal affixed to the material. It allows use of the following powers.</p><ul>\n <li> <i>Astral traveler</i></li>\n <li> <i>Dimension door</i>,  <i>psionic</i></li>\n <li> <i>Teleport</i>,  <i>greater psionic</i></li>\n <li> <i>Teleport</i>,  <i>psionic</i></li>\n</ul><p>Strong psychoportation; ML 15th; Craft Psicrown, <i>astral traveler</i>,  <i>psionic dimension door</i>,  <i>psionic greater teleport</i>,  <i>psionic teleport</i>; Price 80,156 gp.</p><p/>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1640,'Amulet of Catapsi','Universal Items','Psionic','No','Moderate telepathy',NULL,'16,200 gp','9','Craft Universal Item, catapsi',NULL,NULL,'\n      <div topic=\"Amulet of Catapsi\" level=\"8\"><p><b>Amulet of Catapsi:</b> This copper amulet aids the wearer against other psionic characters. Once per day, the wearer can mentally command the <i>catapsi</i> power, which blankets a 30- foot-radius area surrounding the wearer in telepathic noise for 9 rounds. Each time other psionic characters within this range attempt to manifest a power, they must succeed on a DC 17 Will save or pay 4 more points than they otherwise would for each power manifestation. The limit on the number of power points a subject can spend on a power remains in effect, so the subject may not be able to manifest his or her highest-level powers.</p><p>Moderate telepathy; ML 9th; Craft Universal Item, <i>catapsi</i>; Price 16,200 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1641,'Boots of Landing','Universal Items','Psionic','No','Faint psychoportation',NULL,'1,000 gp','2','Craft Universal Item, catfall',NULL,'1 lb','\n      <div topic=\"Boots of Landing\" level=\"8\"><p><b>Boots of Landing:</b> These boots allow the wearer to recover instantly from a fall and can absorb some damage from falling once per day. The wearer lands on her feet no matter how far she falls, and takes 2 fewer dice of damage from the fall than normal.</p><p>Faint psychoportation; ML 2nd; Craft Universal Item, <i>catfall</i>; Price 1,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1642,'Boots of Skating','Universal Items','Psionic','No','Faint psychoportation',NULL,'7,000 gp','1','Craft Universal Item, skate',NULL,'1 lb','\n      <div topic=\"Boots of Skating\" level=\"8\"><p><b>Boots of Skating:</b> These boots allow the wearer to slide along the ground at will as if using the <i>skate</i> power.</p><p>Faint psychoportation; ML 1st; Craft Universal Item, <i>skate</i>; Price 7,000 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1643,'Boots of Stomping','Universal Items','Psionic','No','Faint psychokinesis',NULL,'600 gp','3','Craft Universal Item, stomp',NULL,'1 lb','\n      <div topic=\"Boots of Stomping\" level=\"8\"><p><b>Boots of Stomping:</b> These boots allow the wearer to use <i>stomp</i> as the power three times per day (Reflex save DC 13) when the wearer stomps her feet.</p><p>Faint psychokinesis; ML 3rd; Craft Universal Item, <i>stomp</i>; Price 600 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1644,'Boots of Temporal Acceleration','Universal Items','Psionic','No','Strong psychoportation',NULL,'43,200 gp','15','Craft Universal Item, temporal acceleration',NULL,'1 lb','\n      <div topic=\"Boots of Temporal Acceleration\" level=\"8\"><p><b>Boots of Temporal Acceleration:</b> These boots allow the wearer to speed up his own time frame for 2 rounds as if using the power <i>temporal acceleration</i>. The wearer can use this power once per day.</p><p>Strong psychoportation; ML 15th; Craft Universal Item, <i>temporal acceleration</i>; Price 43,200 gp; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1645,'Crawling Tattoos','Universal Items','Psionic','No','Faint psychokinesis',NULL,'750 gp','5','Craft Universal Item, energy bolt',NULL,NULL,'\n      <div topic=\"Crawling Tattoos\" level=\"8\"><p><b>Crawling Tattoos:</b> Crawling tattoos resemble standard psionic tattoos, but their effects are often harmful rather than beneficial. Like a psionic tattoo, a crawling tattoo can be scribed only with a power of no higher than 3rd level that targets one or more creatures. Exceptions are the <i>body adjustment</i> power, which can be scribed even though it affects only the manifester, and telepathy (compulsion) powers, which cannot be scribed at all. Powers that normally have an area affect only one target if scribed in a crawling tattoo. Powers with an experience point requirement cannot be scribed into a crawling tattoo. Otherwise, crawling tattoos are treated as psionic tattoos until they are activated by the wearer.</p><p>The wearer of a crawling tattoo can tap the tattoo as a standard action that provokes attacks of opportunity, mentally specifying a target (to which the wearer must have line of sight). Instead of manifesting its stored power, the tattoo animates, drops to the ground, and scuttles toward the target. The original wearer need no longer concentrate on the tattoo once animated.</p><p>The animated tattoo moves toward its designated target in the same round when it is activated. Treat it as a Fine construct that has AC 18, 10 hit points, a hardness of 5, speed 30 feet, and a bonus on attack rolls equal to the wearer\'s manifester level + his key ability modifier. Crawling tattoos, unlike true constructs, are subject to illusions, darkness, fog, and similar effects. Should the target be killed, teleport away, or otherwise absent itself before the animated tattoo reaches it, the wearer can reclaim the tattoo. If it is destroyed, a crawling tattoo shatters and evaporates.</p><p>A crawling tattoo must enter the target\'s square to attack and thus provokes attacks of opportunity as it passes through the target\'s threatened area. The tattoo makes one touch attack  per round thereafter until it strikes its target or is destroyed. On a successful attack, the power scribed in the crawling tattoo affects the target if the target fails the appropriate saving throw; however, powers that normally allow a Reflex saving throw automatically affect the touched target. Crawling tattoos can ferry beneficial powers as well as harmful ones, and a target can allow the tattoo\'s touch attack to succeed if he or she desires.</p><p>Two examples of crawling tattoos are described below; many more types are possible.</p><p><i>Market Price:</i> The cost of a crawling tattoo depends on the level of the power scribed in it.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Power Level</b><br/></td> <td><b>Market Price</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1st<br/></td>\n<td>50 gp<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2nd<br/></td>\n<td>300 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>3rd<br/></td>\n<td>750 gp<br/></td>\n\n</tr>\n</table><p><i>Crawling tattoo of concussion</i>: This crawling tattoo delivers a concussion effect, dealing 1d6 points of damage to a creature hit by its touch attack.</p><p>Faint psychokinesis; ML 1st; Craft Universal Item, <i>concussion blast</i>; Price 50 gp.</p><p><i>Crawling Tattoo of Energy Bolt</i>: Each of these tattoos is keyed to one energy type: cold, electricity, fire, or sonic. This crawling tattoo delivers the <i>energy bolt</i> power, dealing 5d6 points of damage of its energy type.</p><p>Faint psychokinesis; ML 5th; Craft Universal Item, <i>energy bolt</i>; Price 750 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1646,'Crystal Anchor','Universal Items','Psionic','No','Faint psychoportation',NULL,'24,000 gp','5','Craft Universal Item, brain lock, psionic contingency, any psychoportation power',NULL,'3 lb','\n      <div topic=\"Crystal Anchor\" level=\"8\"><p><b>Crystal Anchor:</b> A <i>crystal anchor</i> is a shaft of transparent crystal 4 to 5 feet in length, with a sharpened, spearlike head on one end. It ensnares the minds of those within range who manifest powers of a specified psionic discipline. The triggering discipline is specified at the time of creation.</p><p>A <i>crystal anchor</i> is activated by plunging the sharp head into the ground, leaving the shaft freestanding. It projects an invisible, 30-foot-radius field. If a power from the speci- fied discipline is manifested within this range, the manifester must succeed on a Will save (DC 15 + power level) or become subject to an effect similar to <i>brain lock</i>, except that the effect is permanent until dispelled or dismissed by the individual who initially drove the <i>crystal anchor</i> into the earth. Any anchor can be pulled out of the ground and reused at a later time.</p><p>When a <i>crystal anchor</i> successfully ensnares a target, a slender filament of insubstantial ectoplasm connects the victim to the shaft, even one outside the original area of the field.</p><p>A <i>crystal anchor</i> can attempt to ensnare a victim only five times per day. Previously caught targets can remain caught day after day and do not count against this daily limit on attempts.</p><p>An anchor\'s owner can designate certain creatures to be unaffected by the anchor; such creatures need not make a saving throw and do not count against the daily limit on attempts. One <i>crystal anchor</i> can ensnare multiple targets simultaneously, and multiple <i>crystal anchors</i> can share overlapping fields.</p><p>Anchors that activate when a specific power is manifested in range are also possible, but are rarer.</p><p>A <i>crystal anchor</i> has AC 7, 15 hit points, a hardness of 8, and a break DC of 20.</p><p><i>Body Crystal Anchor:</i> Those who manifest psychometabolism powers are affected as described above.</p><p>Faint psychometabolism; ML 5th; Craft Universal Item, <i>brain lock</i>,  <i>psionic contingency</i>, any psychometabolism power; Price 24,000 gp; Weight 3 lb.</p><p><i>Comprehension Crystal Anchor:</i> Those who manifest clairsentience powers are affected as described above.</p><p>Faint clairsentience; ML 5th; Craft Universal Item, <i>brain lock</i>,  <i>psionic contingency</i>, any clairsentience power; Price 24,000 gp; Weight 3 lb.</p><p><i>Creation Crystal Anchor:</i> Those who manifest metacreativity powers are affected as described above.</p><p>Faint metacreativity; ML 5th; Craft Universal Item, <i>brain lock</i>,  <i>psionic contingency</i>, any metacreativity power; Price 24,000 gp; Weight 3 lb.</p><p><i>Energy Crystal Anchor:</i> Those who manifest psychokinesis powers are affected as described above.</p><p>Faint psychokinesis; ML 5th; Craft Universal Item, <i>brain lock</i>,  <i>psionic contingency</i>, any psychokinesis power; Price 24,000 gp; Weight 3 lb.</p><p><i>Ghost Crystal Anchor:</i> Those who manifest <i>remote viewing</i> are affected as described above.</p><p>Faint clairsentience; ML 5th; Craft Universal Item, <i>brain lock</i>,  <i>psionic contingency</i>, <i>remote viewing</i>; Price 24,000 gp; Weight 3 lb.</p><p><i>Mind Crystal Anchor:</i> Those who manifest telepathy powers are affected as described above.</p><p>Faint telepathy; ML 5th; Craft Universal Item, <i>brain lock</i>,  <i>psionic contingency</i>, any telepathy power; Price 24,000 gp; Weight 3 lb.</p><p><i>Travel Crystal Anchor:</i> Those who manifest psychoportation powers are affected as described above.</p><p>Faint psychoportation; ML 5th; Craft Universal Item, <i>brain lock</i>,  <i>psionic contingency</i>, any psychoportation power; Price 24,000 gp; Weight 3 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1647,'Crystal Masks','Universal Items','Psionic','No','Moderate clairsentience',NULL,'10,000 gp','7','Craft Universal Item, creator must have 10 ranks in Psicraft',NULL,'1/2 lb','\n      <div topic=\"Crystal Masks\" level=\"8\"><p><b>Crystal Masks:</b> Each of the various types of crystal masks fits over the face of any Medium or Small humanoid, with slits for eyes and nostrils. The mask is transparent, although it distorts the wearer\'s features. Leather straps attached to small holes on the sides of a mask enable the owner to affix the mask to his face.</p><p>Crystal masks confer special abilities or improved skills on their wearers.</p><p>A crystal mask is treated as eyewear or goggles for the purpose of determining which items can be worn on the body.</p><p><i>Crystal Mask of Detection:</i> The wearer of a <i>crystal mask of detection</i> can make Search checks with a +10 competence bonus.</p><p>Moderate clairsentience; ML 7th; Craft Universal Item, creator must have 10 ranks in Search; Price 10,000 gp; Weight 1/2 lb.</p><p><i>Crystal Mask of Discernment:</i> The wearer of a <i>crystal mask of discernment</i> can make Sense Motive checks with a +10 insight bonus.</p><p>Moderate clairsentience; ML 7th; Craft Universal Item, creator must have 10 ranks in Sense Motive; Price 10,000 gp; Weight 1/2 lb.</p><p><i>Crystal Mask of Dread:</i> The wearer of a <i>crystal mask of dread</i> can attempt to frighten other beings to her will. The wearer makes all Intimidate checks with a +10 competence bonus.</p><p>Moderate clairsentience; ML 7th; Craft Universal Item, creator must have 10 ranks in Intimidate; Price 10,000 gp; Weight 1/2 lb.</p><p><i>Crystal Mask of Insightful Detection:</i> The wearer of a <i>crystal mask of insightful detection</i> can make Search checks and Spot checks checks with a +9 insight bonus.</p><p>Moderate clairsentience; ML 7th; Craft Universal Item, creator must have 9 ranks in both Search and Spot; Price 20,250 gp; Weight 1/2 lb.</p><p><i>Crystal Mask of Knowledge:</i> Each of the various <i>crystal masks of knowledge</i> grants the wearer a +5 competence bonus on a specific type of Knowledge check.</p><p>Faint clairsentience; ML 3rd; Craft Universal Item, creator must have 5 ranks in the Knowledge skill of the appropriate type; Price 2,500 gp; Weight 1/2 lb.</p><p><i>Crystal Mask of Languages:</i> Each of the various <i>crystal masks of language</i> grants the wearer the ability to speak and write five different languages.</p><p>Faint clairsentience; ML 3rd; Craft Universal Item, creator must have the Speak Language skill for each of five languages; Price 2,500 gp; Weight 1/2 lb.</p><p><i>Crystal Mask of Mindarmor:</i> A <i>crystal mask of mindarmor</i> grants the wearer a +4 insight bonus on all Will saving throws.</p><p>Faint telepathy; ML 5th; Craft Universal Item, <i>conceal thoughts</i>; Price 10,667 gp; Weight 1/2 lb.</p><p><i>Crystal Mask of Psionic Craft:</i> The wearer of a <i>crystal mask of psionic craft</i> makes all Psicraft checks with a +10 competence bonus.</p><p>Moderate clairsentience; ML 7th; Craft Universal Item, creator must have 10 ranks in Psicraft; Price 10,000 gp; Weight 1/2 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1648,'Eyes of Expanded Vision','Universal Items','Psionic','No','Faint clairsentience',NULL,'3,000 gp','1','Craft Universal Item, ubiquitous vision',NULL,NULL,'\n      <div topic=\"Eyes of Expanded Vision\" level=\"8\"><p><b>Eyes of Expanded Vision:</b> These crystal lenses fit over the user\'s eyes to expand his field of vision. Flanking opponents gain only a +1 bonus when attacking the user instead of +2 (rogues still get their full sneak attack damage because the wearer is still flanked). The wearer gains a +1 enhancement bonus on Spot checks but takes a -2 penalty on saves against gaze attacks.</p><p>Faint clairsentience; ML 1st; Craft Universal Item, <i>ubiquitous vision</i>; Price 3,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1649,'Eyes of Power Leech','Universal Items','Psionic','No','Moderate telepathy',NULL,'10,080 gp','7','Craft Universal Item, power leech',NULL,NULL,'\n      <div topic=\"Eyes of Power Leech\" level=\"8\"><p><b>Eyes of Power Leech:</b> These crystal lenses fit over the user\'s eyes. Once per day, the wearer is able to drain power points from another psionic creature or character by meeting its gaze as if using <i>power leech</i>. A selected target within 40 feet must succeed on a DC 16 Will save, or a connection of crackling energy is formed between the wearer and the victim. The connection drains 1d6 power points from the target for every round in which the wearer maintains concentration (to a maximum of 7 rounds). The wearer gains 1 power point from those drained from the target each round (subject to his normal maximum; points he cannot gain immediately are lost).</p><p>If the wearer has only one lens, the DC of the Will save is 14 instead of 16.</p><p><i>Eyes of power leech</i> have no effect on nonpsionic targets or psionic creatures with a current power point reserve of 0.</p><p>Moderate telepathy; ML 7th; Craft Universal Item, <i>power leech</i>; Price 10,080 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1650,'Eyes of Power Leech, Vampiric','Universal Items','Psionic','No','Strong telepathy',NULL,'20,160 gp','15','Craft Universal Item, bend reality, power leech',NULL,NULL,'\n      <div topic=\"Eyes of Power Leech, Vampiric\" level=\"8\"><p><b>Eyes of Power Leech, Vampiric:</b> As <i>Eyes of power leech</i>,  except the wearer gains drained power points from the subject even if doing so would bring him over his normal maximum. The wearer of <i>vampiric eyes of power leech</i> can maintain concentration for up to 13 rounds. Power points the wearer gains in excess of his maximum fade after 8 hours if they are not spent before that time.</p><p>Strong telepathy; ML 15th; Craft Universal Item, <i>bend reality</i>,  <i>power leech</i>; Price 20,160 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1651,'Gloves of Object Reading','Universal Items','Psionic','No','Faint clairsentience',NULL,'3,000 gp','1','Craft Universal Item, object reading',NULL,NULL,'\n      <div topic=\"Gloves of Object Reading\" level=\"8\"><p><b>Gloves of Object Reading:</b> While wearing these gloves, the user can learn the details of an inanimate object\'s previous owner if he handles the object, as if manifesting the <i>object reading</i> power.</p><p>Faint clairsentience; ML 1st; Craft Universal Item, <i>object reading</i>; Price 3,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1652,'Gloves of Titan\'s Grip','Universal Items','Psionic','No','Moderate psychometabolism',NULL,'14,000 gp','9','Craft Universal Item, grip of iron',NULL,NULL,'\n      <div topic=\"Gloves of Titan\'s Grip\" level=\"8\"><p><b>Gloves of Titan\'s Grip:</b> While wearing these oversize gloves, the user gains a +8 enhancement bonus on grapple checks. The power is activated when the user enters a grapple. The enhancement bonus lasts for a maximum of 7 rounds per use, up to three uses per day.</p><p>Moderate psychometabolism; ML 9th; Craft Universal Item, <i>grip of iron</i>; Price 14,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1653,'Mirror of Mind Switch','Universal Items','Psionic','No','Moderate telepathy',NULL,'19,800 gp','11','Craft Universal Item, mind switch',NULL,'1/2 lb','\n      <div topic=\"Mirror of Mind Switch\" level=\"8\"><p><b>Mirror of Mind Switch:</b> This small hand mirror manifests its power once per day against a creature that sees its reflection within it, as a gaze attack with a range of 30 feet. Potential victims can attempt to avert their eyes or look away as they would from a normal gaze attack. A creature meeting its own gaze in the mirror must succeed on a DC 19 Will save, or its mind and the mind of the mirror\'s wielder switch, as if by the <i>mind switch</i> power. Because the mirror is small, only a single creature can meet its own gaze. The wielder of the mirror is not affected by seeing himself.</p><p>Moderate telepathy; ML 11th; Craft Universal Item, <i>mind switch</i>; Price 19,800 gp; Weight 1/2 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1654,'Mirror of Suggestion','Universal Items','Psionic','No','Faint telepathy',NULL,'3,600 gp','3','Craft Universal Item, psionic suggestion',NULL,'1/2 lb','\n      <div topic=\"Mirror of Suggestion\" level=\"8\"><p><b>Mirror of Suggestion:</b> This small hand mirror manifests its power up to twice per day against creatures that see their reflections within it, as a gaze attack with a range of 30 feet. Potential victims can attempt to avert their eyes or look away as they would from a normal gaze attack. A creature meeting its own gaze in the mirror must succeed on a DC 13 Will save or be affected by a <i>suggestion</i> chosen by the mirror\'s wielder. Because the mirror is small, only a single creature can meet its own gaze each round. The wielder of the mirror is not affected by seeing herself.</p><p>Faint telepathy; ML 3rd; Craft Universal Item, <i>psionic suggestion</i>; Price 3,600 gp; Weight 1/2 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1655,'Mirror of Time Hop','Universal Items','Psionic','No','Faint psychoportation',NULL,'9,000 gp','5','Craft Universal Item, time hop',NULL,'1/2 lb','\n      <div topic=\"Mirror of Time Hop\" level=\"8\"><p><b>Mirror of Time Hop:</b> This small hand mirror manifests its power up to twice per day against creatures that see their reflections within it, as a gaze attack with a range of 30 feet. Potential victims can attempt to avert their eyes or look away as they would from a normal gaze attack. A creature meeting its own gaze in the mirror must succeed on a DC 14 Will save or be pushed forward in time by 5 rounds, as if subject to the <i>time hop</i> power. Because the mirror is small, only a single creature can meet its own gaze each round. The wielder of the mirror is not affected by seeing herself.</p><p>Faint psychoportation; ML 5th; Craft Universal Item, <i>time hop</i>; Price 9,000 gp; Weight 1/2 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1656,'Pearl, Brain Lock','Universal Items','Psionic','No','Faint telepathy',NULL,'300 gp','3','Craft Universal Item, brain lock',NULL,NULL,'\n      <div topic=\"Pearl, Brain Lock\" level=\"8\"><p><b>Pearl, Brain Lock:</b> This tiny pearly sphere speeds toward its target when hurled by its owner. He can hurl the pearl at any target within 130 feet that he can see and to which he has line of effect. If the target fails a DC 13 Will saving throw, the pearl seems to impact and then enter the flesh of the target. The target stands mentally paralyzed, as if by <i>brain lock</i>,  for 3 rounds. The use destroys the item.</p><p>Faint telepathy; ML 3rd; Craft Universal Item, <i>brain lock</i>; Price 300 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1657,'Pearl, Breath Crisis','Universal Items','Psionic','No','Faint telepathy',NULL,'750 gp','5','Craft Universal Item, crisis of breath',NULL,NULL,'\n      <div topic=\"Pearl, Breath Crisis\" level=\"8\"><p><b>Pearl, Breath Crisis:</b> This tiny pearly sphere speeds toward its target when hurled by its owner. He can hurl the pearl at any target within 150 feet that he can see and to which he has line of effect. If the target fails a DC 14 Will saving throw, the pearl seems to impact and then enter the flesh of the target. The target is affected as if by <i>crisis of breath</i> for 5 minutes. The use destroys the item.</p><p>Faint telepathy; ML 5th; Craft Universal Item, <i>crisis of breath</i>; Price 750 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1658,'Pearl, Mind Seed','Universal Items','Psionic','No','Strong telepathy',NULL,'18,500 gp','15','Craft Universal Item, mind seed','6,000 gp + 2,500 XP',NULL,'\n      <div topic=\"Pearl, Mind Seed\" level=\"8\"><p><b>Pearl, Mind Seed:</b> This tiny pearly sphere instantly takes on the skin tone and texture of whatever creature handles it. It speeds toward its target when hurled by its owner. He can hurl the pearl at any target within 150 feet that he can see and to which he has line of effect. If the target fails a DC 22 Will saving throw, the pearl seems to impact and then enter the flesh of the target. The target is affected as if by a <i>mind seed</i> power, with the pearl\'s wielder acting as the manifester. The use destroys the item.</p><p>Strong telepathy; ML 15th; Craft Universal Item, <i>mind seed</i>; Cost 6,000 gp + 2,500 XP; Price 18,500 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1659,'Pearl, Personality Parasite','Universal Items','Psionic','No','Faint telepathy',NULL,'1,400 gp','7','Craft Universal Item, personality parasite',NULL,NULL,'\n      <div topic=\"Pearl, Personality Parasite\" level=\"8\"><p><b>Pearl, Personality Parasite:</b> This tiny pearly sphere speeds toward its target when hurled by its owner. He can hurl the pearl at any target within 130 feet that he can see and to which he has line of effect. If the target fails a DC 16 Will saving throw, the pearl seems to impact and then enter the flesh of the target. The target is affected as if by <i>personality parasite</i> for 5 rounds. The use destroys the item.</p><p>Faint telepathy; ML 7th; Craft Universal Item, <i>personality parasite</i>; Price 1,400 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1660,'Psionatrix','Universal Items','Psionic','No','Moderate telepathy',NULL,'8,000 gp','8','Craft Universal Item, creator must be a telepath',NULL,NULL,'\n      <div topic=\"Psionatrix\" level=\"8\"><p><b>Psionatrix:</b> Each of these multifaceted crystals is worn as an amulet. Unless noted otherwise, a psionatrix adds a +1 enhancement bonus to the save DC when the wearer uses powers of the discipline to which the psionatrix is keyed.</p><p><i>Psionatrix of clairsentience:</i> Blue light glimmers in this crystal\'s heart.</p><p>Moderate clairsentience; ML 8th; Craft Universal Item, creator must be a seer; Price 8,000 gp.</p><p><i>Psionatrix of metacreativity:</i> Green light glimmers in this crystal\'s heart.</p><p>Moderate metacreativity; ML 8th; Craft Universal Item, creator must be a shaper; Price 8,000 gp.</p><p><i>Psionatrix of psychokinesis:</i> Red light glimmers in this crystal\'s heart.</p><p>Moderate psychokinesis; ML 8th; Craft Universal Item, creator must be a kineticist; Price 8,000 gp.</p><p><i>Psionatrix of psychometabolism:</i> Violet light glimmers in this crystal\'s heart.</p><p>Moderate psychometabolism; ML 8th; Craft Universal Item, creator must be an egoist; Price 8,000 gp.</p><p><i>Psionatrix of psychoportation:</i> Yellow-red light glimmers in this crystal\'s heart.</p><p>Moderate psychoportation; ML 8th; Craft Universal Item, creator must be a nomad; Price 8,000 gp.</p><p><i>Psionatrix of telepathy:</i> Piercing yellow light shines from this crystal\'s heart.</p><p>Moderate telepathy; ML 8th; Craft Universal Item, creator must be a telepath; Price 8,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1661,'Psionic Restraints','Universal Items','Psionic','No','Strong psychokinesis',NULL,NULL,'16','Craft Universal Item, bend reality, dispel psionics',NULL,'1 lb','\n      <div topic=\"Psionic Restraints\" level=\"8\"><p><b>Psionic Restraints:</b> Each of the various psionic restraints is an iron cuff that cunningly locks around the wrist (DC 27 Open Lock check). The cuff limits the total number of power points a psionic creature wearing it can use in 1 round (regardless of the creature\'s total power point reserve), or completely damps the ability to use psionics. All types of psionic restraints prevent the free manifesting of powers.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Restraint Type</b><br/></td>\n<td><b>Allowed Power</b>\n <b>Points/Round</b><br/></td>\n<td><b>Market Price</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Lesser<br/></td>\n<td>5<br/></td>\n<td>1,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Average<br/></td>\n<td>3<br/></td>\n<td>6,000 gp<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Greater<br/></td>\n<td>1<br/></td>\n<td>12,000 gp<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Damping<br/></td>\n<td>0<br/></td>\n<td>24,000 gp<br/></td>\n\n</tr>\n</table><p>Strong psychokinesis; ML 16th; Craft Universal Item, <i>bend reality</i>,  <i>dispel psionics</i>; Weight 1 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1662,'Psychoactive Skins','Universal Items','Psionic','No','Moderate psychometabolism',NULL,'10,000 gp','7','Craft Universal Item, creator must have 10 ranks in Autohypnosis',NULL,NULL,'\n      <div topic=\"Psychoactive Skins\" level=\"8\"><p><b>Psychoactive Skins:</b> Psychoactive skins (also sometimes called ectoshells) are fistsized globs of psionically charged ectoplasm. As a standard action, a psychoactive skin spreads over and covers a Medium or smaller creature that projects the proper command thought; the same command thought causes the skin to shrink back down to its former size. Each of the various psychoactive skins is charged with one of a wide array of powers that constantly affect the wearer.</p><p>A deployed skin completely covers the wearer and all his equipment like a second skin, allowing the wearer to see, hear, and breathe normally. It rolls away from various parts of the body as needed, such as when the wearer needs to eat or access a backpack. Held items or items specifically excluded are not covered by a psychoactive skin.</p><p>Up to three skins can be worn simultaneously, although only the outermost is active in any given round (the powers of hidden skins cannot be manifested). Skin layers can be changed with a command thought as a standard action, which causes a lower-layer skin to come to the surface.</p><p><i>Skin of the Chameleon:</i> This psychoactive skin adjusts to surrounding textures and colors, continually granting the wearer a +10 enhancement bonus on Hide checks.</p><p>Faint psychometabolism; ML 3rd; Craft Universal Item, <i>chameleon</i>; Price 18,000 gp; Weight 2 lb.</p><p><i>Skin of the Claw:</i> This psychoactive skin benefits only a wearer who has levels in psychic warrior. If such a character wears this skin, he can activate the <i>claws of the beast</i> power at will, as a free action that does not provoke attacks of opportunity. He can also dismiss the claws equally quickly.</p><p>Faint psychometabolism; ML 4th; Craft Universal Item, <i>claws of the beast</i>; Price 16,000 gp; Weight 2 lb.</p><p><i>Skin of the Defender:</i> This psychoactive skin continually grants the wearer a +4 bonus to natural armor.</p><p>Faint psychometabolism; ML 5th; Craft Universal Item, <i>thicken skin</i>; Price 32,000 gp; Weight 2 lb.</p><p><i>Skin of Fiery Response:</i> This psychoactive skin answers the first attack made against the wearer in each round with an automatically manifested and targeted \'ectoburst\' against the attacker. The burst ejects from the skin on the wearer\'s turn, making a ranged touch attack as described in the <i>energy retort</i> power, but the energy type chosen is always fire. If the attack hits, the target takes 2d6 points of fire damage as the ectoburst flames up and is consumed. This attack does not in any way hinder the wearer, count against her total actions for the round, or provoke attacks of opportunity.</p><p>Faint psychokinesis; ML 5th; Craft Universal Item, <i>energy retort</i>; Price 60,000 gp; Weight 2 lb.</p><p><i>Skin of the Hero:</i> This psychoactive skin continually grants the wearer a +3 deflection bonus to Armor Class, a +3 resistance bonus on all saving throws, and a +3 enhancement bonus on attack rolls.</p><p>Strong psychometabolism; ML 18th; Craft Universal Item, <i>bend reality</i>; Price 77,500 gp; Weight 2 lb.</p><p><i>Skin of Iron:</i> This psychoactive skin affects the wearer as the <i>psionic iron body</i> power up to three times per day for 15 minutes with each use. When the skin\'s power is not active, it has no protective qualities. Activating the <i>psionic iron body</i> effect is a standard action that provokes attacks of opportunity.</p><p>Strong metacreativity; ML 15th; Craft Universal Item, <i>psionic iron body</i>; Price 129,600 gp; Weight 2 lb.</p><p><i>Skin of Nimbleness:</i> This psychoactive skin continually grants the wearer a +10 competence bonus on Tumble checks.</p><p>Moderate psychometabolism; ML 8th; Craft Universal Item, creator must have 10 ranks in Tumble; Price 10,000 gp; Weight 2 lb.</p><p><i>Skin of Proteus:</i> This psychoactive skin continually affects the wearer as the <i>metamorphosis</i> power. While in a form other than his natural form, the wearer does not appear to be wearing the skin.</p><p>Moderate psychometabolism; ML 7th; Craft Universal Item, <i>metamorphosis</i>; Price 84,000 gp; Weight 2 lb.</p><p><i>Skin of the Psion:</i> This psychoactive skin grants the wearer 7 bonus power points per day and power resistance 21.</p><p>Strong clairsentience; ML 17th; Craft Universal Item, <i>power resistance</i>; Price 151,000 gp; Weight 2 lb.</p><p><i>Skin of the Spider:</i> This psychoactive skin continually grants the wearer a +20 competence bonus on Climb checks and continually affects the wearer as the <i>body equilibrium</i> power. Three times per day, the wearer can manifest <i>entangling ectoplasm</i> against a target within 30 feet.</p><p>Faint psychometabolism; ML 3rd; Craft Universal Item, creator must have 10 ranks in Climb, <i>body equilibrium</i>,  <i>entangling ectoplasm</i>; Price 79,080 gp; Weight 2 lb.</p><p><i>Skin of the Troll:</i> This psychoactive skin continually allows a living wearer to heal more quickly. The wearer heals 5 points of damage per minute. Except for the slower rate of healing, this skin affects its wearer as if the wearer were under the effect of a continual <i>true metabolism</i> power.</p><p>Strong psychometabolism; ML 17th; Craft Universal Item, <i>true metabolism</i>; Price 61,200 gp; Weight 2 lb.</p><p>Ring of Self-Sufficiency: This crystalline ring continually grants the wearer a +10 competence bonus on Autohypnosis checks.</p><p>Moderate psychometabolism; ML 7th; Craft Universal Item, creator must have 10 ranks in Autohypnosis; Price 10,000 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1663,'Shards +1','Universal Items','Psionic','No','Moderate psychometabolism',NULL,'10 gp','7','Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus',NULL,NULL,'\n      <div topic=\"Shards\" level=\"8\"><p><b>Shards:</b> These universal items are tiny fragments of cast-off crystal imprinted with minuscule bits of psionic power. Using a <i>shard</i> requires grasping it and projecting a command thought as a standard action (most <i>shards</i> telepathically whisper their command word into the minds of living creatures who handle them). A <i>shard</i> grants a temporary competence bonus on one specific skill, ranging from +1 to +10. The granted bonus lasts until the skill is used or 10 rounds pass, whichever comes first. Once its effect is activated, a <i>shard</i> disintegrates immediately, whether or not the bonus granted by the <i>shard</i> is eventually used.</p><p>Moderate psychometabolism; ML 7th; Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus; Price 10 gp (+1), 40 gp (+2), 90 gp (+3), 160 gp (+4), 250 gp (+5), 360 gp (+6), 490 gp (+7), 640 gp (+8), 810 gp (+9), or 1,000 gp (+10).</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1664,'Shards +2','Universal Items','Psionic','No','Moderate psychometabolism',NULL,'40 gp','7','Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus',NULL,NULL,'\n      <div topic=\"Shards\" level=\"8\"><p><b>Shards:</b> These universal items are tiny fragments of cast-off crystal imprinted with minuscule bits of psionic power. Using a <i>shard</i> requires grasping it and projecting a command thought as a standard action (most <i>shards</i> telepathically whisper their command word into the minds of living creatures who handle them). A <i>shard</i> grants a temporary competence bonus on one specific skill, ranging from +1 to +10. The granted bonus lasts until the skill is used or 10 rounds pass, whichever comes first. Once its effect is activated, a <i>shard</i> disintegrates immediately, whether or not the bonus granted by the <i>shard</i> is eventually used.</p><p>Moderate psychometabolism; ML 7th; Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus; Price 10 gp (+1), 40 gp (+2), 90 gp (+3), 160 gp (+4), 250 gp (+5), 360 gp (+6), 490 gp (+7), 640 gp (+8), 810 gp (+9), or 1,000 gp (+10).</p>\n</div>\n    ','SRD 3.5 PsionicItems');
