INSERT INTO item VALUES (1670,'Shards +8','Universal Items','Psionic','No','Moderate psychometabolism',NULL,'640 gp','7','Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus',NULL,NULL,'\n      <div topic=\"Shards\" level=\"8\"><p><b>Shards:</b> These universal items are tiny fragments of cast-off crystal imprinted with minuscule bits of psionic power. Using a <i>shard</i> requires grasping it and projecting a command thought as a standard action (most <i>shards</i> telepathically whisper their command word into the minds of living creatures who handle them). A <i>shard</i> grants a temporary competence bonus on one specific skill, ranging from +1 to +10. The granted bonus lasts until the skill is used or 10 rounds pass, whichever comes first. Once its effect is activated, a <i>shard</i> disintegrates immediately, whether or not the bonus granted by the <i>shard</i> is eventually used.</p><p>Moderate psychometabolism; ML 7th; Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus; Price 10 gp (+1), 40 gp (+2), 90 gp (+3), 160 gp (+4), 250 gp (+5), 360 gp (+6), 490 gp (+7), 640 gp (+8), 810 gp (+9), or 1,000 gp (+10).</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1671,'Shards +9','Universal Items','Psionic','No','Moderate psychometabolism',NULL,'810 gp','7','Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus',NULL,NULL,'\n      <div topic=\"Shards\" level=\"8\"><p><b>Shards:</b> These universal items are tiny fragments of cast-off crystal imprinted with minuscule bits of psionic power. Using a <i>shard</i> requires grasping it and projecting a command thought as a standard action (most <i>shards</i> telepathically whisper their command word into the minds of living creatures who handle them). A <i>shard</i> grants a temporary competence bonus on one specific skill, ranging from +1 to +10. The granted bonus lasts until the skill is used or 10 rounds pass, whichever comes first. Once its effect is activated, a <i>shard</i> disintegrates immediately, whether or not the bonus granted by the <i>shard</i> is eventually used.</p><p>Moderate psychometabolism; ML 7th; Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus; Price 10 gp (+1), 40 gp (+2), 90 gp (+3), 160 gp (+4), 250 gp (+5), 360 gp (+6), 490 gp (+7), 640 gp (+8), 810 gp (+9), or 1,000 gp (+10).</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1672,'Shards +10','Universal Items','Psionic','No','Moderate psychometabolism',NULL,'or 1,000 gp','7','Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus',NULL,NULL,'\n      <div topic=\"Shards\" level=\"8\"><p><b>Shards:</b> These universal items are tiny fragments of cast-off crystal imprinted with minuscule bits of psionic power. Using a <i>shard</i> requires grasping it and projecting a command thought as a standard action (most <i>shards</i> telepathically whisper their command word into the minds of living creatures who handle them). A <i>shard</i> grants a temporary competence bonus on one specific skill, ranging from +1 to +10. The granted bonus lasts until the skill is used or 10 rounds pass, whichever comes first. Once its effect is activated, a <i>shard</i> disintegrates immediately, whether or not the bonus granted by the <i>shard</i> is eventually used.</p><p>Moderate psychometabolism; ML 7th; Craft Universal Item, creator must have ranks in the specified skill at least equal to the imprinted bonus; Price 10 gp (+1), 40 gp (+2), 90 gp (+3), 160 gp (+4), 250 gp (+5), 360 gp (+6), 490 gp (+7), 640 gp (+8), 810 gp (+9), or 1,000 gp (+10).</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1673,'Third Eyes','Universal Items','Psionic','No','Moderate clairsentience',NULL,'10,180 gp','7','Craft Universal Item, remote viewing',NULL,NULL,'\n      <div topic=\"Third Eyes\" level=\"8\"><p><b>Third Eyes:</b> These objects appear as small crystals, always with at least one wide, flat facet, and contain a variety of powers. When the owner uses the proper command thought, the crystal adheres to the center of his forehead (the same command thought causes the <i>third eye</i> to disengage). Only one <i>third eye</i> can be worn at a time.</p><p>A <i>third eye</i> is treated as eyewear or goggles for the purpose of determining which items can be worn on the body.</p><p><i>Aware:</i> This kind of <i>third eye</i> continually grants the wearer a +10 competence bonus on Spot checks.</p><p>Moderate clairsentience; ML 7th; Craft Universal Item, creator must have 10 ranks in Spot; Price 10,000 gp.</p><p><i>Conceal:</i> While worn, a <i>third eye conceal</i> protects the wearer from view by all devices, powers, and spells that detect, inf luence, or read emotions or thoughts. This power protects against all mind-affecting powers and effects as well as information-gathering by clairsentience powers or effects (except for <i>metafaculty</i>); this item affects the wearer as if he enjoyed the benefit of the <i>psionic mind blank</i> power.</p><p>Strong telepathy; ML 15th; Craft Universal Item, <i>psionic mind blank</i>; Price 120,000 gp.</p><p><i>Concentrate:</i> This kind of <i>third eye</i> continually grants the wearer a +10 competence bonus on Concentration checks.</p><p>Moderate telepathy; ML 7th; Craft Universal Item, creator must have 10 ranks in Concentration; Price 10,000 gp.</p><p><i>Dominate:</i> The wearer of a <i>third eye dominate</i> can attempt to dominate a subject as with the power <i>psionic dominate</i>,  augmented to target any creature type it can affect, once per day (save DC 18).</p><p>Strong telepathy; ML 15th; Craft Universal Item, <i>psionic dominate</i>; Price 120,000 gp.</p><p><i>Expose:</i> The wearer of this kind of <i>third eye</i> always knows when someone lies directly to him.</p><p>Strong telepathy; ML 15th; Craft Universal Item, <i>bend reality</i>; Price 112,000 gp.</p><p><i>Gather:</i> This kind of <i>third eye</i> continually grants the wearer a +10 competence bonus on Gather Information checks.</p><p>Moderate clairsentience; ML 7th; Craft Universal Item, creator must have 10 ranks in Gather Information; Price 10,000 gp.</p><p><i>Penetrate:</i> While worn, a <i>third eye penetrate</i> grants the wearer a +2 bonus on manifester level checks to overcome a creature\'s power resistance.</p><p>Strong clairsentience; ML 15th; Craft Universal Item, <i>bend reality</i>; Price 8,000 gp.</p><p><i>Powerthieve:</i> While worn, a <i>third eye powerthieve</i> allows the wearer to borrow one power from a psionic target within 40 feet once per day. If the target fails a DC 16 Will save, it instantly loses one power of the wearer\'s choice, and the wearer instantly gains temporary knowledge of this power.</p><p>The wearer can manifest the borrowed power normally if she has sufficient power points to pay for its cost. The wearer retains knowledge of the power for up to 70 minutes, at which time she loses knowledge of the power and the former owner regains it, regardless of the distance between them. If the former owner is dead, the wearer still loses the borrowed power.</p><p>Moderate telepathy; ML 7th; Craft Universal Item, <i>thieving mindlink</i>; Price 10,080 gp.</p><p><i>Repudiate:</i> While worn, this powerful item allows the wearer to manifest <i>dispel psionics</i> once per day with a +20 modifier on the dispel check (the wearer uses the +20 modifier in place of his manifester level).</p><p>Strong psychokinesis; ML 20th; Craft Universal Item, <i>dispel psionics</i>; Price 43,200 gp.</p><p><i>Sense</i>: The wearer of this kind of <i>third eye</i> can manifest <i>clairvoyant sense</i> at will.</p><p>Faint clairsentience; ML 3rd; Craft Universal Item, <i>clairvoyant sense</i>; Price 24,000 gp.</p><p><i>View:</i> The wearer of this kind of <i>third eye</i> can spin a quasireal version of himself and send it over virtually any distance or into other planes of existence, as if manifesting the <i>remote viewing</i> power, once per day.</p><p>Moderate clairsentience; ML 7th; Craft Universal Item, <i>remote viewing</i>; Price 10,180 gp.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1674,'Torc of Free Will','Universal Items','Psionic','No','Faint telepathy',NULL,'6,000 gp','3','Craft Universal Item, brain lock',NULL,'2 lb','\n      <div topic=\"Torc of Free Will\" level=\"8\"><p><b>Torc of Free Will:</b> This item is a band inlaid with precious metal, worn around the neck or upper arm. The wearer of a <i>torc of free will</i> is not affected by the <i>brain lock</i> power or items that produce <i>brain lock</i> effects (such as <i>crystal anchors</i>).</p><p>A torc is treated as an amulet for the purpose of determining which items can be worn on the body.</p><p>Faint telepathy; ML 3rd; Craft Universal Item, <i>brain lock</i>; Price 6,000 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1675,'Torc of Leech Freedom','Universal Items','Psionic','No','Faint telepathy',NULL,'12,000 gp','5','Craft Universal Item, power leech',NULL,'2 lb','\n      <div topic=\"Torc of Leech Freedom\" level=\"8\"><p><b>Torc of Leech Freedom:</b> This item is a band inlaid with precious metal, worn around the neck or upper arm. The wearer of a <i>torc of leech freedom</i> automatically resists up to two uses of <i>power leech</i> against him per day.</p><p>A torc is treated as an amulet for the purpose of determining which items can be worn on the body.</p><p>Faint telepathy; ML 5th; Craft Universal Item, <i>power leech</i>; Price 12,000 gp; Weight 2 lb.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1676,'Torc of Power Preservation','Universal Items','Psionic','No','Strong clairsentience',NULL,'36,000 gp','15','Craft Universal Item, bend reality',NULL,'2 lb','\n      <div topic=\"Torc of Power Preservation\" level=\"8\"><p><b>Torc of Power Preservation:</b> This item is a band inlaid with precious metal, worn around the neck or upper arm. The wearer of a <i>torc of power preservation</i> manifests all powers by paying power points equal to the standard cost minus 1 (minimum of 1).</p><p>A torc is treated as an amulet for the purpose of determining which items can be worn on the body.</p><p>Strong clairsentience; ML 15th; Craft Universal Item, <i>bend reality</i>; Price 36,000 gp; Weight 2 lb.</p><p/>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1677,'Reverse Capacitor','Cursed','Psionic','No','Strong telepathy',NULL,'112,000 gp','15','Craft Universal Item, bend reality, power leech',NULL,'1 lb','\n      <div topic=\"Reverse Capacitor\" level=\"8\"><p><b>Reverse Capacitor:</b> A <i>reverse capacitor</i> doesn\'t store power points-it drains them, to the surprise and chagrin of a psionic character taken in by its resemblance to a <i>cognizance crystal</i>. Powers that identify psionic items incorrectly identify a <i>reverse capacitor</i> as a <i>cognizance crystal</i> 50% of the time.</p><p>A psionic character attempting to use the power points supposedly stored in a <i>reverse capacitor</i> instead loses 1d6 power points per round for 7 rounds. A crackling arc connects the brow of the character with the stone. If the character can put more than 40 feet between himself and the <i>reverse capacitor</i>,  the effect ends. If the <i>reverse capacitor</i> drains more power points than the psionic character possesses, the draining effect ends.</p><p>The drained power points are simply lost. Each new attempt to use the power points supposedly stored in the <i>reverse capacitor</i> initiates the draining effect anew.</p><p>Strong telepathy; ML 15th; Craft Universal Item, <i>bend reality</i>,  <i>power leech</i>; Price 112,000 gp; Weight 1 lb.</p><p/>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1678,'Sutra of Tranquil Thought','Artifact','Psionic, Minor Artifact','No','Strong telepathy',NULL,NULL,'20',NULL,NULL,'3 lb','\n      <div topic=\"Sutra of Tranquil Thought\" level=\"8\"><p><b>Sutra of Tranquil Thought:</b> This monastic tome describes ancient techniques of mental focus and is highly prized by psionic practitioners. If a psionic character who is not evil studies the work during one week of solitary contemplation, he gains 17 bonus power points and experience points sufficient to place him halfway into the next level of experience. Those who use their powers for evil are punished for their impertinence, losing 5d6 x 1,000 XP for defiling the book. In addition, an evil reader must make an immediate DC 15 Will save or become permanently <i>confused</i> as if affected by the <i>insanity</i> power. Only <i>psychic chirurgery</i> or similarly extreme measures can restore sanity.</p><p>The minds of nonpsionic beings are too clouded to benefit from the secrets of this book. To anyone without psionic aptitude, the book\'s pages appear to contain nothing but elaborate patterns and drawings of mysterious beings. Once it is read, the book vanishes into the Astral Plane to an unknown destination. Even if it is found again, the same character cannot benefit twice from perusing its contents.</p><p>Strong telepathy; ML 20th; Weight 3 lb.</p><p/>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1679,'Annulus','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Annulus\" level=\"8\"><p><b>Annulus:</b> This artifact is the ultimate psionic nullifier. Forged to keep enemies of vast psionic power at bay, the <i>Annulus</i> is an artifact that any psionic being should fear. It has been forgotten in the modern age, and merely finding it would precipitate a great upheaval across the planes.</p><p>The <i>Annulus</i> is a 1-foot-diameter ring of silvery material. Tiny slots, antennae, spheres, and other intricate projections decorate the exterior of the hoop; however, two smoothed lengths of the ring provide an adequate surface for grasping the item.</p><p>The <i>Annulus</i> has several powers, all of which require a wielder to tightly grasp the ring with at least one hand. When it is first grasped, knowledge of the artifact\'s powers immediately flood the wielder\'s mind. The wielder can access all powers of the <i>Annulus</i> at manifester level 20th.</p><ul>\n <li> The <i>Annulus</i> generates a continuous <i>catapsi</i> effect within a 100-foot-radius of the wielder (who is unaffected).</li>\n <li> The wielder gains a +4 enhancement bonus on any attempt to resist an effect that deals ability damage.</li>\n <li> Once per day, the wielder can trigger <i>ultrablast</i> as a standard action.</li>\n <li> Three times per day, as a standard action, the wielder can trigger an effect similar to <i>psionic dimensional anchor</i> that affects all creatures in a 50-foot radius.</li>\n</ul><p>The primary power of the <i>Annulus</i>,  however, is psionic nullification. Once per year, the wielder can trigger this effect as a special action requiring 10 rounds of continuous concentration to complete. The wielder specifies a target or targets within a 100-foot radius, ranging from a specific psionic individual or item to a group of psionic beings that share the same philosophy. The nullification effect is accompanied by blasts of light, heat, and sound from the <i>Annulus</i>. Nonpsionic creatures and items are unaffected, as are nontargeted beings, but any psionic target-regardless of any protection it may possess-disintegrates in a terrific explosion. Nothing is left but floating dust.</p><p>It is relatively easy to nullify a single target or a small group of targets, but nullifying a more powerful being (such as a demigod or greater entity) or another major artifact taxes the <i>Annulus</i> to its limits. If it is used to nullify such a target, the artifact succeeds but is destroyed in the process and cannot be retrieved by any means.</p>\n</div>\n    ','SRD 3.5 PsionicItems');
INSERT INTO item VALUES (1680,'Psicrown of the Crystal Mind','Artifact','Major Artifact','No',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Psicrown of the Crystal Mind\" level=\"8\"><p><b>Psicrown of the Crystal Mind:</b> An elaborate crystalline psicrown etched with strange designs, this exceptional psicrown is so invested with power that it is considered an artifact.</p><p>The power points in the <i>Psicrown of the Crystal Mind</i> can be used to manifest any of the following powers at manifester level 20th (or at the wearer\'s manifester level if it is higher than 20th).</p><ul>\n <li> <i>Burst</i></li>\n <li> <i>Catfall</i></li>\n <li> C<i>oncealing amorpha</i>,  <i>greater</i></li>\n <li> <i>Concussion blast</i></li>\n <li> <i>Daze</i>,  <i>psionic</i></li>\n <li> <i>Detect psionics</i></li>\n <li> <i>Dominate</i>,  <i>psionic</i></li>\n <li> <i>Far hand</i></li>\n <li> <i>Float</i></li>\n <li> <i>Mindlink</i></li>\n <li> <i>Inertial barrier</i></li>\n <li> <i>Telekinetic force</i></li>\n <li> <i>Telekinetic maneuver</i></li>\n <li> <i>Telekinetic thrust</i></li>\n <li> <i>Teleport</i>,  <i>psionic</i></li>\n <li> <i>Thicken skin</i></li>\n <li> <i>True metabolism</i></li>\n</ul><p>The wearer of the <i>Psicrown of the Crystal Mind</i> also gains power resistance equal to 10 + his manifester level.</p><p>The <i>Psicrown of the Crystal Mind</i> has 1,000 power points when discovered. Anyone who dons the crown instantly knows the number of power points it has at the current time. The crown recharges itself, gaining back 1 power point per day if it currently has fewer than 1,000 points.</p><p>As a special one-time use of the psicrown, the wearer can channel all the remaining charges in the psicrown into an uncontrolled burst of energy. The wearer triggers this use as a standard action. All within 20 feet of the wearer take hit points of damage equal to half the power points left in the staff (Reflex DC 18 half). The wearer inhabits a tiny eye of calm at the center of the destruction and is unharmed, but the psicrown is reduced to a burned-out cinder.</p><p/>\n</div>\n    ','SRD 3.5 PsionicItems');
